# -*- coding: utf-8 -*-
"""
Generate comprehensive grammar tasks for all 44 units (21 tasks per unit = 924 tasks).
Combined with 105 existing = 1029 tasks.
"""
import json
from pathlib import Path

units_tasks = {}

def add_tasks(unit_id, level, skill_title, task_tuples):
    tasks = []
    for idx, t in enumerate(task_tuples, 1):
        task_obj = {
            "id": f"gt-{unit_id}-{idx:02d}",
            "type": t[0],
            "prompt": t[1],
            "answers": t[2] if isinstance(t[2], list) else [t[2]],
            "explanation": t[3],
            "skill": skill_title,
            "level": level
        }
        if len(t) > 4 and t[4]:
            task_obj["options"] = t[4]
        tasks.append(task_obj)
    units_tasks[unit_id] = tasks

# Helper for choice options
def opts(correct, wrongs):
    import random
    arr = [correct] + wrongs
    random.seed(len(correct) + len(wrongs))
    random.shuffle(arr)
    return arr


